from playwright.sync_api import Locator, Page


class AuthPage:
    """Login and register share one template, so one page object covers both."""

    def __init__(self, page: Page):
        self.page = page
        self.error = page.get_by_test_id("error")

    def open_login(self) -> "AuthPage":
        self.page.goto("/login")
        return self

    def open_register(self) -> "AuthPage":
        self.page.goto("/register")
        return self

    def submit(self, username: str, password: str) -> None:
        self.page.get_by_test_id("username").fill(username)
        self.page.get_by_test_id("password").fill(password)
        self.page.get_by_test_id("submit").click()


class BooksPage:
    def __init__(self, page: Page):
        self.page = page
        self.error = page.get_by_test_id("error")
        self.rows = page.get_by_test_id("book-row")
        self.empty_state = page.get_by_test_id("empty-state")
        self.current_user = page.get_by_test_id("current-user")

    def open(self) -> "BooksPage":
        self.page.goto("/books")
        return self

    def row(self, title: str) -> Locator:
        return self.rows.filter(has_text=title)

    def add(self, title: str, author: str, year: str = "") -> None:
        self.page.get_by_test_id("title").fill(title)
        self.page.get_by_test_id("author").fill(author)
        self.page.get_by_test_id("year").fill(year)
        self.page.get_by_test_id("add-books").click()

    def delete(self, title: str) -> None:
        self.row(title).get_by_test_id("delete-book").click()

    def log_out(self) -> None:
        self.page.get_by_test_id("logout").click()
